def is_prime(n: int) -> bool:
    return all(n % i != 0 for i in range(2, int(n ** 0.5) + 1))

def prime_factors(n: int) -> list[int]:
    factors = []
    for i in range(2, int(n ** 0.5) + 1):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 1:
        factors.append(n)
    return factors

return max(prime_factors(n))

